INSERT INTO easa_subjects (module_id, code, title, sort_order) VALUES
  (10, 'M10.8', 'Exam Question Bank', 8)
    INSERT INTO questions (subject_id, text, options, licence_types) VALUES
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A register of airlines operating on an AOC is maintained by the.', '[{"id": "a", "text": "ICAO.", "correct": false}, {"id": "b", "text": "CAA.", "correct": true}, {"id": "c", "text": "FAA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'For UK registered aircraft, components must be.', '[{"id": "a", "text": "maintained by a part-145 approved organisation.", "correct": false}, {"id": "b", "text": "any appropriately approved organisation.", "correct": true}, {"id": "c", "text": "maintained by a part-145 approved organisation registered in the UK.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Safe operation of the aircraft is the responsibility of the.', '[{"id": "a", "text": "part-M organisation.", "correct": false}, {"id": "b", "text": "owner.", "correct": false}, {"id": "c", "text": "operator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The validity of an EASA permit to fly is.', '[{"id": "a", "text": "12 months.", "correct": true}, {"id": "b", "text": "7 days.", "correct": false}, {"id": "c", "text": "as stated on the certificate but not exceeding 14 days.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Where would you normally train for licences?.', '[{"id": "a", "text": "At a Part-147 approved organisation.", "correct": true}, {"id": "b", "text": "At a Part-145 approved organisation.", "correct": false}, {"id": "c", "text": "At a technical training school.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'To what does a B1-3 License apply to?.', '[{"id": "a", "text": "Helicopter with turbines, their engines, airframes and electrics.", "correct": true}, {"id": "b", "text": "Light aircraft with piston engines.", "correct": false}, {"id": "c", "text": "Helicopters with piston engines, their engines, airframes and electrics.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'What can an A1 licensed engineer sign for?.', '[{"id": "a", "text": "Minor Scheduled Line Maintenance tasks on turbine engined helicopters.", "correct": false}, {"id": "b", "text": "Minor Scheduled Line Maintenance tasks on turbine engined aircraft. [CLOSEST INTENDED", "correct": true}, {"id": "c", "text": "Minor Scheduled Line Maintenance tasks on piston engined aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Who can sign a CRS?.', '[{"id": "a", "text": "Any licensed engineer.", "correct": false}, {"id": "b", "text": "An appropriately licensed engineer.", "correct": true}, {"id": "c", "text": "An unlicensed engineer who has permission from the Chief Inspector.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Where would you find the requirements and the syllabus for a maintenance license?.', '[{"id": "a", "text": "EASA Part-147.", "correct": false}, {"id": "b", "text": "EASA Part-145.", "correct": false}, {"id": "c", "text": "EASA Part-66.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An A1 licensed mechanic can sign for.', '[{"id": "a", "text": "Aeroplanes and Helicopters.", "correct": false}, {"id": "b", "text": "Aeroplanes - Piston.", "correct": false}, {"id": "c", "text": "Aeroplanes - Turbine.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Part-66 licence can be used without amendment or exchange.', '[{"id": "a", "text": "only in the member state in which it was issued.", "correct": false}, {"id": "b", "text": "throughout all member states.", "correct": true}, {"id": "c", "text": "throughout the World.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A part-66 licence holder wishing to work in another member state apart from the one it was issued, must have a licence printed in.', '[{"id": "a", "text": "English.", "correct": true}, {"id": "b", "text": "only the originating member state''s language.", "correct": false}, {"id": "c", "text": "the language of the member state which the holder wishes to work in.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Who issues a part-66 licence?.', '[{"id": "a", "text": "EASA.", "correct": false}, {"id": "b", "text": "A part 145 organisation.", "correct": false}, {"id": "c", "text": "The competent authority of the member state.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Whose responsibility is it that no unauthorised entries are made in a part-66 licence?.', '[{"id": "a", "text": "EASA or the national aviation authority of the member state.", "correct": false}, {"id": "b", "text": "The licence holder.", "correct": true}, {"id": "c", "text": "The part-145 organisation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'EASA Form 26 is.', '[{"id": "a", "text": "the application for a part-66 licence.", "correct": false}, {"id": "b", "text": "the application for an extension to a part-66 licence.", "correct": false}, {"id": "c", "text": "the part-66 licence itself.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A part-66 licence is issued for.', '[{"id": "a", "text": "initially 2 years then re-issued for a period of 5 years.", "correct": false}, {"id": "b", "text": "initially 5 years then re-issued for a period of 2 years.", "correct": false}, {"id": "c", "text": "5 years.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A B2 License applies to.', '[{"id": "a", "text": "line maintenance on airframe structure and powerplants.", "correct": false}, {"id": "b", "text": "line maintenance on electrical systems and avionics.", "correct": true}, {"id": "c", "text": "line maintenance on airframe structure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'What does a B1- 3 approval apply to?.', '[{"id": "a", "text": "Light Aircraft with Piston Engines.", "correct": false}, {"id": "b", "text": "Helicopters with Turbine Engines, airframe and electrics.", "correct": true}, {"id": "c", "text": "Helicopters with Piston Engines, airframe and electrics.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A category A licence.', '[{"id": "a", "text": "is automatically issued with a category B1 licence.", "correct": true}, {"id": "b", "text": "is automatically issued with a category B2 licence.", "correct": false}, {"id": "c", "text": "is automatically issued with both a category B1 and B2 licence.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Who carries out the practical task training required for a category A licence?.', '[{"id": "a", "text": "Either a part-145 or a part-147 organisation.", "correct": true}, {"id": "b", "text": "A part-147 organisation only.", "correct": false}, {"id": "c", "text": "A part-145 organisation only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Who is responsible for the control and issue of engineers licenses?.', '[{"id": "a", "text": "EASA.", "correct": false}, {"id": "b", "text": "CAA.", "correct": true}, {"id": "c", "text": "JAA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'When can a LAE sign a CRS?.', '[{"id": "a", "text": "For any aircraft for which he has a type rating.", "correct": false}, {"id": "b", "text": "For any aircraft for which his company has Part-145 approval.", "correct": false}, {"id": "c", "text": "For any aircraft for which he has a type endorsement on his license and holds the appropriate", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'If an engineer has an aircraft maintenance basic license he/she can.', '[{"id": "a", "text": "not sign anything, there are no certification rights offered by the license alone. [CLOSEST", "correct": true}, {"id": "b", "text": "sign the CRS.", "correct": false}, {"id": "c", "text": "sign the CRS, as the license implies the rights of certification.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Within an aircraft maintenance organisation approved in accordance with IR Part-145, the limitations of an individual''s certification rights are recorded upon.', '[{"id": "a", "text": "the personnel authorisation certificate.", "correct": true}, {"id": "b", "text": "the aircraft maintenance licence.", "correct": false}, {"id": "c", "text": "the personnel records.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The term ''Extension'' of a Part-66 licence means.', '[{"id": "a", "text": "to extend its validity for a further period of time.", "correct": false}, {"id": "b", "text": "to add an additional basic category.", "correct": true}, {"id": "c", "text": "to add a type approval.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Category-A Part-66 licensed engineer can certify for work carried out.', '[{"id": "a", "text": "by him/herself only.", "correct": true}, {"id": "b", "text": "by anyone within an approved organisation.", "correct": false}, {"id": "c", "text": "by anyone, even if they are independent of an approved organisation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A part-66 licensed engineer must be able to speak.', '[{"id": "a", "text": "the language of the technical documentation and procedures for the maintenance of the aircraft", "correct": true}, {"id": "b", "text": "English.", "correct": false}, {"id": "c", "text": "the language of the European Member State which issued his/her licence.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An aircraft type approval endorsement to a Part-66 licence is only provided after.', '[{"id": "a", "text": "adequate theoretical training.", "correct": false}, {"id": "b", "text": "adequate theoretical and practical training.", "correct": true}, {"id": "c", "text": "adequate practical training.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'EASA IR Part-66 applies to aircraft.', '[{"id": "a", "text": "below 5700 kg only.", "correct": false}, {"id": "b", "text": "above and below 5700 kg.", "correct": true}, {"id": "c", "text": "above 5700 kg only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'What experience is required for an A1 license.', '[{"id": "a", "text": "2 yrs or 1 yr if qualified in another profession.", "correct": false}, {"id": "b", "text": "3 yrs or 2 yrs if qualified in another profession. [CLOSEST INTENDED ANSWER]", "correct": true}, {"id": "c", "text": "5 yrs or 3 yrs if trained by 147 company.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The usual qualification route for a Category C licensed engineer is.', '[{"id": "a", "text": "3 years experience as a B1.1, B1.3 or B2 engineer.", "correct": true}, {"id": "b", "text": "8 years experience as a B1.1, B1.3 or B2 engineer.", "correct": false}, {"id": "c", "text": "5 years experience as a B1.1, B1.3 or B2 engineer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An EASA category A licensed mechanic can.', '[{"id": "a", "text": "certify minor line tasks which he has done himself and for which he has approval. [REVIEWED", "correct": true}, {"id": "b", "text": "certify minor line tasks which he or other line mechanics have done and for which he has approval.", "correct": false}, {"id": "c", "text": "certify line maintenance checks.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Which of the following are the sub-sections of a Part-66 maintenance licence in category A?.', '[{"id": "a", "text": "Aeroplanes - Piston, helicopters Piston, Aeroplanes -Turbine and Helicopters Turbine.", "correct": true}, {"id": "b", "text": "Aeroplanes - Piston and helicopters Piston.", "correct": false}, {"id": "c", "text": "Aeroplanes - Turbine and helicopters Turbine.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Part-66 A licensed engineer can.', '[{"id": "a", "text": "sign the CRS for minor line maintenance, within the limits of tasks specifically endorsed on the", "correct": true}, {"id": "b", "text": "sign the CRS for any line maintenance and defect repairs.", "correct": false}, {"id": "c", "text": "sign the CRS for any minor line repairs as long as they have the aircraft type stamped in their license.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An A licence is automatically granted with the issue of which of the following?.', '[{"id": "a", "text": "B1 or B2.", "correct": false}, {"id": "b", "text": "B1.", "correct": true}, {"id": "c", "text": "B2.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'IR Part-66 experience requirements may be reduced with.', '[{"id": "a", "text": "aircraft production experience.", "correct": false}, {"id": "b", "text": "completion of training at a Part-147 approved school.", "correct": true}, {"id": "c", "text": "completion of a university engineering degree.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A category C certifying staff authorisation permits the holder to issue a block CRS after.', '[{"id": "a", "text": "base maintenance.", "correct": true}, {"id": "b", "text": "line maintenance and defect rectification.", "correct": false}, {"id": "c", "text": "any line or base maintenance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An EASA IR B1.2 engineer can certify.', '[{"id": "a", "text": "aircraft - turbine engined.", "correct": false}, {"id": "b", "text": "aircraft -both turbine and piston engined.", "correct": false}, {"id": "c", "text": "aircraft - piston engined.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An EASA IR B1.3 engineer can certify.', '[{"id": "a", "text": "helicopters - both turbine and piston engined.", "correct": false}, {"id": "b", "text": "helicopters - piston engined.", "correct": false}, {"id": "c", "text": "helicopters - turbine engined.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'How long is an EASA part-66 licence valid?.', '[{"id": "a", "text": "2 years once signed in ink.", "correct": false}, {"id": "b", "text": "5 years once signed and verified that the information contained in the licence is the same as that", "correct": true}, {"id": "c", "text": "5 years once signed in ink.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Part-145 organisation based outside the EU, the competent authority is.', '[{"id": "a", "text": "the CAA.", "correct": false}, {"id": "b", "text": "the NAA of the country it is located in.", "correct": false}, {"id": "c", "text": "the EASA.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A CRS must be issued.', '[{"id": "a", "text": "only if an aircraft part is replaced with a new part.", "correct": false}, {"id": "b", "text": "if an aircraft part is removed then re- installed, even if it is the same part.", "correct": true}, {"id": "c", "text": "only when an aircraft part is replaced with a modified part.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Who is a Part- 145 approved organisation headed by?.', '[{"id": "a", "text": "The Technical Manager.", "correct": false}, {"id": "b", "text": "The QA Manager.", "correct": false}, {"id": "c", "text": "The Accountable Manager.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'When the block CRS is finally issued for base maintenance at a Part-145 organisation, who is ultimately responsible for maintenance carried out during the check?.', '[{"id": "a", "text": "the Category B LAE.", "correct": false}, {"id": "b", "text": "the Category C LAE.", "correct": true}, {"id": "c", "text": "the Accountable Manager.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Part-145 approval is not required to carry out.', '[{"id": "a", "text": "daily checks (as long as 48 hours has not passed).", "correct": false}, {"id": "b", "text": "defect rectification.", "correct": false}, {"id": "c", "text": "pre-flight checks.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'How long does an licensed engineer have to produce his/her authorisation certification if asked by the CAA or EASA?.', '[{"id": "a", "text": "immediately.", "correct": false}, {"id": "b", "text": "7 days.", "correct": false}, {"id": "c", "text": "24 hours.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Part-145 approved maintenance organisation is authorised to.', '[{"id": "a", "text": "approve major modifications.", "correct": false}, {"id": "b", "text": "issue certificates for work completed in aircraft maintenance or overhaul.", "correct": true}, {"id": "c", "text": "originate repair schemes and manufacture parts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Who can sign the CRS?.', '[{"id": "a", "text": "LAE.", "correct": false}, {"id": "b", "text": "LAE who has the permission from the chief inspector.", "correct": false}, {"id": "c", "text": "LAE who is authorised to do so.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A situation is found which could hazard an aircraft, while it is undergoing maintenance by a Part-145 organisation. The situation must be reported within.', '[{"id": "a", "text": "48 hours.", "correct": false}, {"id": "b", "text": "24 hours.", "correct": false}, {"id": "c", "text": "72 hours.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Part-145 organisation finds a condition on an aircraft which could be hazardous, they must inform the CAA within.', '[{"id": "a", "text": "3 days.", "correct": true}, {"id": "b", "text": "24 hours.", "correct": false}, {"id": "c", "text": "7 days.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'For which type of maintenance do you not need a Part-145 approval?.', '[{"id": "a", "text": "Hangar Base Maintenance.", "correct": false}, {"id": "b", "text": "Preflight inspection.", "correct": true}, {"id": "c", "text": "Weekly Check.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Part-145 company is required to be headed by.', '[{"id": "a", "text": "a technical director.", "correct": false}, {"id": "b", "text": "a licensed engineer.", "correct": false}, {"id": "c", "text": "an accountable manager.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Unserviceable aircraft equipment should not be stored.', '[{"id": "a", "text": "in a goods-in store.", "correct": false}, {"id": "b", "text": "on unserviceable shelves around the hangar.", "correct": false}, {"id": "c", "text": "with serviceable spares.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Under the Part- 145 Approval System an A1 Rating relates to aircraft.', '[{"id": "a", "text": "on base maintenance only.", "correct": false}, {"id": "b", "text": "of 5700 kg MTOM and below.", "correct": false}, {"id": "c", "text": "exceeding 5700 kg MTOM.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Following the replacement and compensation of a direct reading compass certification is made in the form of a.', '[{"id": "a", "text": "certificate of compensation.", "correct": false}, {"id": "b", "text": "certificate of conformity.", "correct": false}, {"id": "c", "text": "CRS.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The Authorised Release Certificate EASA Form 1 can.', '[{"id": "a", "text": "have several items entered onto it providing they are identical part numbers.", "correct": false}, {"id": "b", "text": "have several items entered onto it of different part numbers.", "correct": true}, {"id": "c", "text": "have only one item entered onto it.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Following satisfactory aircraft component replacement, adjustment, locking and functioning. Which of the following is issued?.', '[{"id": "a", "text": "Certificate of maintenance review.", "correct": false}, {"id": "b", "text": "CRS.", "correct": true}, {"id": "c", "text": "A maintenance statement.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The authorised release certificate EASA form one is.', '[{"id": "a", "text": "issued from the tech log prior to the flight.", "correct": false}, {"id": "b", "text": "an international parts release document issued by approved organisations. [REVIEWED", "correct": true}, {"id": "c", "text": "used to return or release unserviceable components from the aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An EASA form 1.', '[{"id": "a", "text": "may be in English or the language of the country to which the component to which it refers to, is being", "correct": false}, {"id": "b", "text": "must be printed in English regardless of the language of the country to which the component to", "correct": true}, {"id": "c", "text": "must be printed in the language of the country to which the component to which it refers to, is being", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The wording of a CRS issued by a Part-145 organisation can be found in.', '[{"id": "a", "text": "", "correct": false}, {"id": "b", "text": "EASA Part-145 Section", "correct": false}, {"id": "c", "text": "The Acceptable Means of Compliance to EASA Part 145.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The EASA Form 1 is to be used when components are.', '[{"id": "a", "text": "both exported/imported and bought/sold domestically.", "correct": true}, {"id": "b", "text": "exported or imported only.", "correct": false}, {"id": "c", "text": "used bought and sold domestically only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'After a mandatory inspection has been carried out by a Licensed Engineer, what is issued?.', '[{"id": "a", "text": "Certificate of Release to Service.", "correct": true}, {"id": "b", "text": "A Flight Release Certificate.", "correct": false}, {"id": "c", "text": "A Certificate of Maintenance Review.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'When an item is removed from an aircraft, then subsequently refitted.', '[{"id": "a", "text": "no certificate of release to service is required if it is the same item.", "correct": false}, {"id": "b", "text": "only one certificate of release to service is required to cover both the removal and the re-", "correct": true}, {"id": "c", "text": "two certificates of release to service is required to cover the removal and the re- fitment respectively.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'If a temporary wiring repair has to be carried out on an aircraft which is away from its Maintenance Organization, how would this be certified?.', '[{"id": "a", "text": "No Certification need be made.", "correct": false}, {"id": "b", "text": "Aircraft would be certified as Fit for Flight under ''A'' conditions.", "correct": false}, {"id": "c", "text": "By signing a Certificate of Release to Service.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A company has approval reference of form EASA.145.00X? It is located.', '[{"id": "a", "text": "outside a European Member State.", "correct": true}, {"id": "b", "text": "in the USA.", "correct": false}, {"id": "c", "text": "within a European Member State.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'On completion of the overhaul of an aircraft component by an overhaul organization.', '[{"id": "a", "text": "the worksheets with a certified CRS are retained by the overhaul organization and an EASA form", "correct": true}, {"id": "b", "text": "the worksheets with a certified CRS are placed in the aircraft file with the log books.", "correct": false}, {"id": "c", "text": "the worksheets are retained by the overhaul organization in their own files.", "correct": false}]'::jsonb, '{B1,B2}'),
