    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An A licence is automatically granted with the issue of which of the following?', '[{"id": "a", "text": "B1 or B2.", "correct": false}, {"id": "b", "text": "B1.", "correct": true}, {"id": "c", "text": "B2.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'IR Part-66 experience requirements may be reduced with', '[{"id": "a", "text": "aircraft production experience.", "correct": false}, {"id": "b", "text": "completion of training at a Part-147 approved school.", "correct": true}, {"id": "c", "text": "completion of a university engineering degree.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A category C certifying staff authorisation permits the holder to issue a block CRS after', '[{"id": "a", "text": "base maintenance.", "correct": true}, {"id": "b", "text": "line maintenance and defect rectification.", "correct": false}, {"id": "c", "text": "any line or base maintenance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An EASA IR B1.2 engineer can certify', '[{"id": "a", "text": "aircraft - turbine engined.", "correct": false}, {"id": "b", "text": "aircraft -both turbine and piston engined.", "correct": false}, {"id": "c", "text": "aircraft - piston engined.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An EASA IR B1.3 engineer can certify', '[{"id": "a", "text": "helicopters - both turbine and piston engined.", "correct": false}, {"id": "b", "text": "helicopters - piston engined.", "correct": false}, {"id": "c", "text": "helicopters - turbine engined.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Part-145 organisation based outside the EU, the competent authority is', '[{"id": "a", "text": "the CAA.", "correct": false}, {"id": "b", "text": "the NAA of the country it is located in.", "correct": false}, {"id": "c", "text": "the EASA.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Who is a Part-145 approved organisation headed by?', '[{"id": "a", "text": "The Technical Manager.", "correct": false}, {"id": "b", "text": "The QA Manager.", "correct": false}, {"id": "c", "text": "The Accountable Manager.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'When the block CRS is finally issued for base maintenance at a Part-145 organisation, who is', '[{"id": "a", "text": "ultimately responsible for maintenance carried out during the check?", "correct": false}, {"id": "b", "text": "the Category B LAE.", "correct": false}, {"id": "c", "text": "the Category C LAE.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Part-145 approval is not required to carry out', '[{"id": "a", "text": "daily checks (as long as 48 hours has not passed.", "correct": false}, {"id": "b", "text": "defect rectification.", "correct": false}, {"id": "c", "text": "pre-flight checks.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An approved Part-145 organisation is one which is', '[{"id": "a", "text": "of a standard acceptable to the CAA and the FAA.", "correct": false}, {"id": "b", "text": "of a standard acceptable to the EU.", "correct": true}, {"id": "c", "text": "of a standard as defined in the ANO.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Part-145 approved maintenance organisation is authorised to', '[{"id": "a", "text": "approve major modifications.", "correct": false}, {"id": "b", "text": "issue certificates for work completed in aircraft maintenance or overhaul.", "correct": true}, {"id": "c", "text": "originate repair schemes and manufacture parts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Who can sign the CRS?', '[{"id": "a", "text": "LAE.", "correct": false}, {"id": "b", "text": "LAE who has the permission from the chief inspector.", "correct": false}, {"id": "c", "text": "LAE who is authorised to do so.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'If you are required to produce your License, this must be done', '[{"id": "a", "text": "immediately.", "correct": false}, {"id": "b", "text": "within 24 hours.", "correct": true}, {"id": "c", "text": "within a reasonable time.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Part-145 organisation finds a condition on an aircraft which could be hazardous, they must', '[{"id": "a", "text": "inform the CAA within", "correct": false}, {"id": "b", "text": "3 days", "correct": true}, {"id": "c", "text": "24 hours.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'In a Part-145 company, who is responsible for keeping technical information on certifying staff?', '[{"id": "a", "text": "Tech Records.", "correct": false}, {"id": "b", "text": "Quality Assurance.", "correct": true}, {"id": "c", "text": "Personnel Department.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Who monitors how a company is adhering to Part-145?', '[{"id": "a", "text": "Base Maintenance Manager.", "correct": false}, {"id": "b", "text": "Accountable Manager.", "correct": false}, {"id": "c", "text": "Quality Manager.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'For which type of maintenance do you not need a Part-145 approval?', '[{"id": "a", "text": "Hangar Base Maintenance.", "correct": false}, {"id": "b", "text": "Preflight inspection.", "correct": true}, {"id": "c", "text": "Weekly Check.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Part-145 company is required to be headed by', '[{"id": "a", "text": "a technical director.", "correct": false}, {"id": "b", "text": "a licensed engineer.", "correct": false}, {"id": "c", "text": "an accountable manager.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Unserviceable aircraft equipment should not be stored', '[{"id": "a", "text": "in a goods-in store.", "correct": false}, {"id": "b", "text": "on unserviceable shelves around the hangar.", "correct": false}, {"id": "c", "text": "with serviceable spares.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Under the Part-145 Approval System an A1 Rating relates to aircraft', '[{"id": "a", "text": "on base maintenance only.", "correct": false}, {"id": "b", "text": "of 5700 kg MTOM and below.", "correct": false}, {"id": "c", "text": "exceeding 5700 kg MTOM.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The Approval Reference Number for a typical Part-145 company would be', '[{"id": "a", "text": "AI/1234/94.", "correct": false}, {"id": "b", "text": "CAA 00023.", "correct": false}, {"id": "c", "text": "UK.145.00505.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The responsibility for reporting incidents and occurrences during a flight rests with the', '[{"id": "a", "text": "aircraft commander.", "correct": true}, {"id": "b", "text": "engineer clearing the tech log.", "correct": false}, {"id": "c", "text": "air stewards.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The minimum distribution of the Authorised Release Certificate EASA Form 1 is', '[{"id": "a", "text": "1, to remain with the component to which it refers.", "correct": false}, {"id": "b", "text": "2, one for the originator and one to remain with the component to which it refers.", "correct": true}, {"id": "c", "text": "1, to be retained by the originator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The Authorised Release Certificate EASA Form 1 can', '[{"id": "a", "text": "have several items entered onto it providing they are identical part numbers.", "correct": false}, {"id": "b", "text": "have several items entered onto it of different part numbers.", "correct": true}, {"id": "c", "text": "have only one item entered onto it.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Following satisfactory aircraft component replacement, adjustment, locking and functioning.', '[{"id": "a", "text": "Which of the following is issued?", "correct": false}, {"id": "b", "text": "Certificate of maintenance review.", "correct": false}, {"id": "c", "text": "CRS.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The wording of a CRS issued by a Part-145 organisation can be found in', '[{"id": "a", "text": "the ANO.", "correct": false}, {"id": "b", "text": "EASA Part-145 Section A.", "correct": false}, {"id": "c", "text": "The Acceptable Means of Compliance to EASA Part 145.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Independent audits of a department within a Part-145 approved organisation are to be carried', '[{"id": "a", "text": "out at least every", "correct": false}, {"id": "b", "text": "6 months.", "correct": false}, {"id": "c", "text": "12 month.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The EASA Form 1 is to be used when components are', '[{"id": "a", "text": "both exported/imported and bought/sold domestically.", "correct": true}, {"id": "b", "text": "exported or imported only.", "correct": false}, {"id": "c", "text": "used bought and sold domestically only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'After a mandatory inspection has been carried out by a Licensed Engineer, what is issued?', '[{"id": "a", "text": "Certificate of Release to Service.", "correct": true}, {"id": "b", "text": "A Flight Release Certificate.", "correct": false}, {"id": "c", "text": "A Certificate of Maintenance Review.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'When an item is removed from an aircraft, then subsequently refitted', '[{"id": "a", "text": "no certificate of release to service is required if it is the same item.", "correct": false}, {"id": "b", "text": "only one certificate of release to service is required to cover both the removal and the re-fitment.", "correct": true}, {"id": "c", "text": "two certificates of release to service is required to cover the removal and the re-fitment respectively.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'For the purposes of EASA Part-145, a ''Large aircraft'' is', '[{"id": "a", "text": "over 13610 kg MTOM.", "correct": false}, {"id": "b", "text": "over 2730 kg MTOM.", "correct": false}, {"id": "c", "text": "over 5700 kg MTOM.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A company has approval reference of form EASA.145.00X? It is located', '[{"id": "a", "text": "outside a European Member State.", "correct": true}, {"id": "b", "text": "in the USA.", "correct": false}, {"id": "c", "text": "within a European Member State", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Signatories to the CRS will be found in', '[{"id": "a", "text": "Airworthiness Notice No.3.", "correct": false}, {"id": "b", "text": "the organization exposition.", "correct": true}, {"id": "c", "text": "BCAR Section A-8/13, A-8/15, A-8/3.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The staffing requirements for an organization approved to undertake maintenance on', '[{"id": "a", "text": "commercial transport aircraft are to be found in", "correct": false}, {"id": "b", "text": "EASA IR Part-145.30.", "correct": true}, {"id": "c", "text": "JAR E.25D.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The extent of an organisation''s Part-145 approval is stated', '[{"id": "a", "text": "on the approval certificate.", "correct": true}, {"id": "b", "text": "in the CAA''s list of approved organisations.", "correct": false}, {"id": "c", "text": "in the organisation''s exposition.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'To comply with IR Part-145', '[{"id": "a", "text": "the Acceptable Means of Compliance can be used.", "correct": true}, {"id": "b", "text": "any additional national directives must be used.", "correct": false}, {"id": "c", "text": "JAA Joint Circulars should be used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The list of typical tasks which cat-A line maintenance mechanic may perform is contained in', '[{"id": "a", "text": "Part 145.", "correct": true}, {"id": "b", "text": "Part 147.", "correct": false}, {"id": "c", "text": "Part 66.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An aircraft component which comes with an EASA form 1,', '[{"id": "a", "text": "will not need a CRS when fitted as a form 1 is also a CRS.", "correct": false}, {"id": "b", "text": "will also require a form 8130-3 if fitted to a British aircraft.", "correct": false}, {"id": "c", "text": "will require a CRS to be issued when fitted to certify correct installation as the form 1 CRS applies only to", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An organisation seeking approval to carry out maintenance on an aeroplane of 6000kg MTWA', '[{"id": "a", "text": "carrying cargo only, would apply for approval under", "correct": false}, {"id": "b", "text": "CS 25.", "correct": false}, {"id": "c", "text": "IR Part-145.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Category C licensed engineers are backed up by', '[{"id": "a", "text": "engineers holding existing BCAR section-L licence in the appropriate category.", "correct": false}, {"id": "b", "text": "hanger based cat B1 and B2 licensed maintenance technicians and mechanics with appropriate type ratings.", "correct": false}, {"id": "c", "text": "cat B1 and B2 technicians with type rating.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Part-66 certifying staff must be', '[{"id": "a", "text": "not less than 21 years of age.", "correct": true}, {"id": "b", "text": "There is no Age limitation.", "correct": false}, {"id": "c", "text": "not less than 18 years of age.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'What aircraft can an EASA part-145 company maintain?', '[{"id": "a", "text": "Commercial Air Transport aircraft only.", "correct": false}, {"id": "b", "text": "All aircraft over 5700 kg MTOM.", "correct": false}, {"id": "c", "text": "All aircraft on its schedule of approval.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'How long have you got, to produce a Part-66 licence when asked to do so?', '[{"id": "a", "text": "Within 7 days.", "correct": false}, {"id": "b", "text": "Within 5 days.", "correct": false}, {"id": "c", "text": "Within 24 hours.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An aircraft has an unapproved repair.', '[{"id": "a", "text": "Issue a CRS to approve it.", "correct": false}, {"id": "b", "text": "Issue a Fitness for Flight cert.", "correct": false}, {"id": "c", "text": "It cannot be certified until the repair is approved.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The requirement for having a Quality Department to a maintenance organisation are set out in', '[{"id": "a", "text": "IR Part 21.", "correct": false}, {"id": "b", "text": "IR Part M.", "correct": false}, {"id": "c", "text": "IR Part-145.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The responsibility for regularly weighing aircraft rests with the', '[{"id": "a", "text": "operator.", "correct": true}, {"id": "b", "text": "Part-145 maintenance organisation.", "correct": false}, {"id": "c", "text": "CAA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Documents to be carried include', '[{"id": "a", "text": "Certificate of Registration, Airworthiness, Insurance and Radio License.", "correct": true}, {"id": "b", "text": "C of A, Permit to Fly, radio License, Crew Licenses, and C of R.", "correct": false}, {"id": "c", "text": "Crew licenses, radio licence and aircraft dealers certificate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Aircraft types which an operator can fly are listed in the', '[{"id": "a", "text": "Aircraft Flight Manual.", "correct": false}, {"id": "b", "text": "Air Operators Certificate.", "correct": true}, {"id": "c", "text": "Company Maintenance Schedule.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An aircraft registered in the UK and operating in the transport category will normally be', '[{"id": "a", "text": "operated", "correct": false}, {"id": "b", "text": "by the holder of an AOC.", "correct": true}, {"id": "c", "text": "Under B conditions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Deferred defects are recorded in', '[{"id": "a", "text": "the Deferred defect manual.", "correct": false}, {"id": "b", "text": "the Technical Log.", "correct": true}, {"id": "c", "text": "the Technical Manual.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Which of the following documents must be carried on an aircraft?', '[{"id": "a", "text": "Certificate of Registration.", "correct": true}, {"id": "b", "text": "Air operators Certificate.", "correct": false}, {"id": "c", "text": "Engine Log Book.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Large Aircraft Maintenance Schedules are produced by', '[{"id": "a", "text": "manufacturer with CAA approval.", "correct": false}, {"id": "b", "text": "operator.", "correct": true}, {"id": "c", "text": "CAA Safety Regulation Group.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Aircraft over 5700kg MTOM are weighed', '[{"id": "a", "text": "at the renewal of the Certificate of Airworthiness.", "correct": false}, {"id": "b", "text": "prior to entry into service and then every 4 years.", "correct": true}, {"id": "c", "text": "annually.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Which of the following form part of the aircraft Technical Log?', '[{"id": "a", "text": "Future maintenance program for the pilots information.", "correct": true}, {"id": "b", "text": "Pilots name and number.", "correct": false}, {"id": "c", "text": "CRS and weight and balance information.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Which of the following documents are to be carried on an aircraft?', '[{"id": "a", "text": "Tech log, full Operations Manual and Flight Manual.", "correct": false}, {"id": "b", "text": "Tech Log and parts of the Operations Manual.", "correct": true}, {"id": "c", "text": "Full Operations Manual and Flight Manual.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Who approves the aircraft Technical Log?', '[{"id": "a", "text": "The Part-145 organisation maintaining the aircraft.", "correct": false}, {"id": "b", "text": "The operator.", "correct": false}, {"id": "c", "text": "The National aviation authority.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A type certificate is', '[{"id": "a", "text": "issued after a Certificate of Registration.", "correct": false}, {"id": "b", "text": "issued before a Certificate of Airworthiness.", "correct": true}, {"id": "c", "text": "issued after a Certificate of Airworthiness.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Type Certificate is a', '[{"id": "a", "text": "requirement prior to the issue of a C of A for aircraft in the Transport Category.", "correct": false}, {"id": "b", "text": "requirement for aircraft above 2730Kg MTWA.", "correct": false}, {"id": "c", "text": "prerequisite to the issue of a C of A.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A design organisation is approved in accordance with', '[{"id": "a", "text": "IR Part-21.", "correct": true}, {"id": "b", "text": "IR Part-145.", "correct": false}, {"id": "c", "text": "BCARs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Type Certificate is issued to', '[{"id": "a", "text": "an aircraft type and its variants.", "correct": true}, {"id": "b", "text": "all aircraft of a type (e.g. A340).", "correct": false}, {"id": "c", "text": "each aircraft of a type.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A type certificate issued to an aircraft by the CAA', '[{"id": "a", "text": "shows approval of the design by the CAA only.", "correct": false}, {"id": "b", "text": "shows approval of the design by the CAA and would be approved under EASA.", "correct": false}, {"id": "c", "text": "shows approval of the design by the CAA but will not necessarily be approved under EASA.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An EASA Part-145 organisation may classify repairs as major or minor if approved in', '[{"id": "a", "text": "accordance with", "correct": false}, {"id": "b", "text": "EASA Part-145.", "correct": false}, {"id": "c", "text": "EASA Part-21 subpart J.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'To what stage of flight is a Noise Certificate applicable?', '[{"id": "a", "text": "Take-off and landing.", "correct": true}, {"id": "b", "text": "All stages of flight.", "correct": false}, {"id": "c", "text": "Take-off only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'What could invalidate a Noise Certificate?', '[{"id": "a", "text": "A modification.", "correct": true}, {"id": "b", "text": "An unauthorised or unapproved repair is carried out.", "correct": false}, {"id": "c", "text": "Once issued, nothing can invalidate it.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'On completion of a major modification to an EASA aircraft, for the purposes of a flight test', '[{"id": "a", "text": "issue a Certificate of Fitness to Fly since the C of A has been invalidated.", "correct": false}, {"id": "b", "text": "the C of A is valid providing it is still within the date shown on it.", "correct": false}, {"id": "c", "text": "issue a Permit to Fly.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'What Certificate must an Operator have who flies for public transport and cargo carrying?', '[{"id": "a", "text": "Air Navigation Certificate.", "correct": false}, {"id": "b", "text": "Air Transport Licence.", "correct": false}, {"id": "c", "text": "Air Operators Certificate.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A certificate of airworthiness is a requirement of', '[{"id": "a", "text": "IR Part-21.", "correct": true}, {"id": "b", "text": "JAR OPS.", "correct": false}, {"id": "c", "text": "IR Part-M.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'What is the period of validity for a Certificate of Registration?', '[{"id": "a", "text": "Until a change of ownership or maintenance arrangements.", "correct": false}, {"id": "b", "text": "Until a change of ownership.", "correct": true}, {"id": "c", "text": "The same as for the aircrafts C of A.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A series EASA aircraft flying for the approval of a major modification flies under', '[{"id": "a", "text": "A conditions.", "correct": false}, {"id": "b", "text": "a permit to fly.", "correct": true}, {"id": "c", "text": "B conditions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A radio station license becomes invalid', '[{"id": "a", "text": "whenever a radio Flight test is required.", "correct": false}, {"id": "b", "text": "upon change of ownership of aircraft.", "correct": true}, {"id": "c", "text": "when the c of a is due for renewal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A certificate of approval of Aircraft Radio Installation is issued to', '[{"id": "a", "text": "an aircraft.", "correct": true}, {"id": "b", "text": "an air operator.", "correct": false}, {"id": "c", "text": "a company approved for such installations.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The purpose for which an aircraft may be flown on a special category C of A is', '[{"id": "a", "text": "applicable to ex military aircraft only.", "correct": false}, {"id": "b", "text": "stated on the certificate.", "correct": true}, {"id": "c", "text": "for private use only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A permit to fly is valid', '[{"id": "a", "text": "for 12 months.", "correct": false}, {"id": "b", "text": "until the date stated on it.", "correct": true}, {"id": "c", "text": "only for evaluating a modification.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The period of validity of an EASA C of A is', '[{"id": "a", "text": "as stated on certificate.", "correct": false}, {"id": "b", "text": "36 months.", "correct": false}, {"id": "c", "text": "indefinite.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An aircraft with a Standard category C of A may be used for', '[{"id": "a", "text": "any purpose.", "correct": true}, {"id": "b", "text": "carrying passenger and/or freight only.", "correct": false}, {"id": "c", "text": "carrying passengers only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Cof R is renewable', '[{"id": "a", "text": "when aircraft is sold abroad.", "correct": false}, {"id": "b", "text": "every year.", "correct": false}, {"id": "c", "text": "when ownership changes in U.K. only.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A C.of R', '[{"id": "a", "text": "is issued by Ministry of Trade and Industry.", "correct": false}, {"id": "b", "text": "may not be issued if aircraft could be more suitable registered elsewhere.", "correct": true}, {"id": "c", "text": "is valid only in country of origin.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Noise certificate is valid for', '[{"id": "a", "text": "unlimited duration.", "correct": true}, {"id": "b", "text": "until a change in ownership of the aircraft to an owner located in another member state.", "correct": false}, {"id": "c", "text": "until a change in ownership of the aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'If an EASA aircraft is required to be flown without a C of A, for the issue of a C of A', '[{"id": "a", "text": "an EASA Permit to Fly is applied for.", "correct": true}, {"id": "b", "text": "it can be flown with special permission from the competent authority.", "correct": false}, {"id": "c", "text": "it can be flown under A Conditions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A British aircraft manufacturer must apply for a Certificate of Airworthiness', '[{"id": "a", "text": "to the Department of Trade and Industry.", "correct": false}, {"id": "b", "text": "to the I.C.A.O.", "correct": false}, {"id": "c", "text": "to the C.A.A.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A Noise Certificate is a requirement of', '[{"id": "a", "text": "IR Part-21.", "correct": true}, {"id": "b", "text": "JAR OPS.", "correct": false}, {"id": "c", "text": "IR Part-M.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A new imported series aircraft requires flight testing prior to the issue of its first UK C of A. this', '[{"id": "a", "text": "flight test should be carried out under", "correct": false}, {"id": "b", "text": "A Conditions of the A.N.O.", "correct": false}, {"id": "c", "text": "an EASA Permit to Fly.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Which of the following would an EASA Permit to Fly NOT be used for?', '[{"id": "a", "text": "To proceed to a place where the aircraft will be painted.", "correct": false}, {"id": "b", "text": "To fly passengers or cargo domestically.", "correct": true}, {"id": "c", "text": "To check a modification.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'How many copies of the Certificate of Registration are required?', '[{"id": "a", "text": "Two copies, one for the flight manual, one for the filing system.", "correct": false}, {"id": "b", "text": "Two copies, one for the owner, one for the aircraft.", "correct": false}, {"id": "c", "text": "one copy for the owner/operator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Mandatory equipment required to be fitted on an aircraft would be found in', '[{"id": "a", "text": "BCAR Section C.", "correct": false}, {"id": "b", "text": "BCAR Section K or EASA Part-21 CS 25.", "correct": true}, {"id": "c", "text": "BCAR Section E.", "correct": false}]'::jsonb, '{B1,B2}'),
