    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The certificate of registration becomes invalid if', '[{"id": "a", "text": "the AOC is termed invalid.", "correct": false}, {"id": "b", "text": "it is found that the aircraft is registered in another country.", "correct": true}, {"id": "c", "text": "the C of A is invalid.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A radio installation is', '[{"id": "a", "text": "a C of R requirement.", "correct": false}, {"id": "b", "text": "an operational requirement.", "correct": true}, {"id": "c", "text": "a C of A requirement.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'When does a noise certificate not have to be carried?', '[{"id": "a", "text": "When leaving and arriving at the same aerodrome.", "correct": true}, {"id": "b", "text": "When in UK.", "correct": false}, {"id": "c", "text": "When in an EC member state.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'In a company with a Part-M approval, an Airworthiness Review Certificate may be signed by', '[{"id": "a", "text": "any employee holding an appropriate licence.", "correct": false}, {"id": "b", "text": "qualified persons nominated by the company.", "correct": true}, {"id": "c", "text": "no-one, it is not required under Part-M.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'What is the retention time for a Technical Log?', '[{"id": "a", "text": "2 years after the last entry.", "correct": false}, {"id": "b", "text": "2 years.", "correct": false}, {"id": "c", "text": "3 years after the last entry.", "correct": true}]'::jsonb, '{B1,B2}'),
