    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Maintenance of large aircraft must be carried out by', '[{"id": "a", "text": "a part-M approved organisation.", "correct": false}, {"id": "b", "text": "a part-145 approved organisation.", "correct": true}, {"id": "c", "text": "a part-147 approved organisation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'All outstanding deferred defect rectifications are recorded in', '[{"id": "a", "text": "the flight manual.", "correct": false}, {"id": "b", "text": "the operator''s technical log.", "correct": true}, {"id": "c", "text": "the appropriate Log Book.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An airworthiness review certificate, when issue, is valid for', '[{"id": "a", "text": "1 year.", "correct": true}, {"id": "b", "text": "3 years.", "correct": false}, {"id": "c", "text": "indefinitely, until varied, suspended or revoked.", "correct": false}]'::jsonb, '{B1,B2}'),
