    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A staff member of a Part-M organisation authorised to issue or recommend issue of an', '[{"id": "a", "text": "airworthiness review certificate", "correct": false}, {"id": "b", "text": "need not be part 66 qualified.", "correct": true}, {"id": "c", "text": "must be both Part-66 qualified and have an aeronautical degree.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The persons authorised to issue or recommend issue of an airworthiness review certificate are', '[{"id": "a", "text": "listed", "correct": false}, {"id": "b", "text": "in the company exposition.", "correct": true}, {"id": "c", "text": "on the airworthiness review certificate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'The operator of an aircraft used for commercial air transport', '[{"id": "a", "text": "need not be approved to IR Part-145 providing they are contracted to a Part-145 organisation.", "correct": true}, {"id": "b", "text": "must be approved to IR Part-M only.", "correct": false}, {"id": "c", "text": "must be approved to IT Part-145.", "correct": false}]'::jsonb, '{B1,B2}'),
