    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'An airworthiness review certificate can be extended', '[{"id": "a", "text": "twice only.", "correct": true}, {"id": "b", "text": "once only.", "correct": false}, {"id": "c", "text": "It cannot be extended, it must be re-issued.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Continued airworthiness is the responsibility of', '[{"id": "a", "text": "the owner or lessee.", "correct": true}, {"id": "b", "text": "the part-M company.", "correct": false}, {"id": "c", "text": "the part-145 company.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'A pre-flight inspection', '[{"id": "a", "text": "can be carried out only by an A, B1 or B2 licensed, type rated and Part-145 company approved engineer.", "correct": false}, {"id": "b", "text": "can be carried out only by an A or B1 licensed, type rated and Part-145 company approved engineer.", "correct": false}, {"id": "c", "text": "does not require Part-145 approval for carrying-out.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'Under EASA how long does the Technical Log have to be retained?', '[{"id": "a", "text": "5 years after the last entry.", "correct": false}, {"id": "b", "text": "2 years after the last entry.", "correct": false}, {"id": "c", "text": "3 years after the last entry.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M10.8'), 'If, at a major check, there is too much documentation to go into the log book', '[{"id": "a", "text": "a CRS is raised to cover the documentation, and the documentation is then discarded.", "correct": false}, {"id": "b", "text": "a new log book is raised.", "correct": false}, {"id": "c", "text": "the documentation is stored elsewhere and the logbook is cross referred to it.", "correct": true}]'::jsonb, '{B1,B2}'),
